// import colorFrag from './shaders/color.frag.wgsl';

import { CameraController } from './Camera/CameraController';
// import { loadWGSL } from 'njscore';

import { loadWGSL } from './lib';

import * as triangle from './triangle';
import { mat4 } from 'gl-matrix';

import vertPath from './shaders/vert.glsl';
import fragPath from './shaders/frag.glsl';

// import vertPath from './shaders/vert.glsl';
// import fragPath from './shaders/frag.glsl';


export class Solution {
    divHost: HTMLElement;
    canvas: HTMLCanvasElement;
    ctx: GPUCanvasContext;
    device: GPUDevice;
    format: GPUTextureFormat;
    size: any;
    pipelineObj: any;

    cameraController: CameraController;

    constructor(id: string) {
        this.divHost = document.getElementById(id) as HTMLDivElement;
        
        // tslint:disable: no-console
        this.canvas = document.createElement('canvas');
        this.divHost.appendChild(this.canvas);
        this.canvas.width = this.divHost.clientWidth ;
        this.canvas.height = this.divHost.clientHeight;

        this.init();
    }
    async init() {
        this.cameraController = new CameraController(this);

        // const vertShader = vertPath; // await loadWGSL(vertPath);
        // const fragShader = fragPath; // await loadWGSL(fragPath);

        const vertShader = await loadWGSL(vertPath);
        const fragShader = await loadWGSL(fragPath);

        // const fragShader = "#version 300 es\n#pragma vscode_glsllint_stage: frag\n\nprecision mediump float;\n\nin vec4 vColor;\n\nout vec4 fragColor;\n\nvoid main()\n{\n    fragColor = vColor;\n}"
        // const vertShader = "#version 300 es\n#pragma vscode_glsllint_stage: vert\n\nuniform mat4 uModel;\nuniform mat4 uView;\nuniform mat4 uProjection;\nuniform mat4 cameraProjection;\n\n\nlayout(location=0) in vec4 aPosition;\nlayout(location=1) in vec4 aColor;\n\nout vec4 vColor;\n\nvoid main()\n{\n    vColor = aColor;\n    gl_Position = cameraProjection * uModel * aPosition;\n}"

        // console.log({vertShader, fragShader})

        const gl = this.canvas.getContext('webgl2') as WebGL2RenderingContext;

        const program = gl.createProgram() as WebGLProgram;

        const vertexShader = gl.createShader(gl.VERTEX_SHADER) as WebGLShader;
        gl.shaderSource(vertexShader, vertShader as string);
        gl.compileShader(vertexShader);
        gl.attachShader(program, vertexShader);

        const fragmentShader = gl.createShader(gl.FRAGMENT_SHADER) as WebGLShader;
        gl.shaderSource(fragmentShader, fragShader as string);
        gl.compileShader(fragmentShader);
        gl.attachShader(program, fragmentShader);

        gl.linkProgram(program);

        if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
        //     console.log(gl.getShaderInfoLog(vertexShader));
        //     console.log(gl.getShaderInfoLog(fragmentShader));
        }

        gl.useProgram(program);

        gl.enable(gl.DEPTH_TEST);

        const vertexData = new Float32Array([
            -.5,-.5,-.5,   0,1,1,
            -.5, .5, .5,   0,1,1,
            -.5, .5,-.5,   0,1,1,
            -.5,-.5, .5,   0,1,1,
            -.5, .5, .5,   0,1,1,
            -.5,-.5,-.5,   0,1,1,
    
            .5 ,-.5,-.5,   1,0,1,
            .5 , .5,-.5,   1,0,1,
            .5 , .5, .5,   1,0,1,
            .5 , .5, .5,   1,0,1,
            .5 ,-.5, .5,   1,0,1,
            .5 ,-.5,-.5,   1,0,1,
    
            -.5,-.5,-.5,   0,1,0,
            .5,-.5,-.5,   0,1,0,
            .5,-.5, .5,   0,1,0,
            .5,-.5, .5,   0,1,0,
            -.5,-.5, .5,   0,1,0,
            -.5,-.5,-.5,   0,1,0,
    
            -.5, .5,-.5,   1,1,0,
            .5, .5, .5,   1,1,0,
            .5, .5,-.5,   1,1,0,
            -.5, .5, .5,   1,1,0,
            .5, .5, .5,   1,1,0,
            -.5, .5,-.5,   1,1,0,
    
            .5,-.5,-.5,   0,0,1,
            -.5,-.5,-.5,   0,0,1,
            .5, .5,-.5,   0,0,1,
            -.5, .5,-.5,   0,0,1,
            .5, .5,-.5,   0,0,1,
            -.5,-.5,-.5,   0,0,1,
    
            -.5,-.5, .5,   1,0,0,
            .5,-.5, .5,   1,0,0,
            .5, .5, .5,   1,0,0,
            .5, .5, .5,   1,0,0,
            -.5, .5, .5,   1,0,0,
            -.5,-.5, .5,   1,0,0,
        ]);
    
        const vertexBuffer = gl.createBuffer();
        gl.bindBuffer(gl.ARRAY_BUFFER, vertexBuffer);
        gl.bufferData(gl.ARRAY_BUFFER, vertexData, gl.STATIC_DRAW);
        gl.vertexAttribPointer(0, 3, gl.FLOAT, false, 24, 0);
        gl.vertexAttribPointer(1, 3, gl.FLOAT, false, 24, 12);
        gl.enableVertexAttribArray(0);
        gl.enableVertexAttribArray(1);
        
        const modelLoc = gl.getUniformLocation(program, 'uModel');
        const viewLoc = gl.getUniformLocation(program, 'uView');
        const projectionLoc = gl.getUniformLocation(program, 'uProjection');
        const cameraLoc = gl.getUniformLocation(program, 'cameraProjection');

        const model = mat4.create();
        const view = mat4.create();
        const projection = mat4.create();

        mat4.rotateZ(model, model, 0.0);
        mat4.scale(model, model, [.8, .8, .8]);
        mat4.lookAt(view, [1,1,0], [0,0,0], [0,1,0]);

        mat4.perspective(projection, Math.PI / 1.5, gl.canvas.width / gl.canvas.height, .1, 10);
        // mat4.ortho(projection, -1,1, -1,1, -1,2);

        gl.uniformMatrix4fv(viewLoc, false, view);
        gl.uniformMatrix4fv(projectionLoc, false, projection);


        const draw = () => {
            requestAnimationFrame(draw);

            // gl.viewport(0, 0, gl.canvas.width, gl.canvas.height);

            // gl.enable(gl.CULL_FACE);
            // gl.enable(gl.DEPTH_TEST);
        
            // // Clear the canvas AND the depth buffer.
            // gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);
            
            this.cameraController.update();

            mat4.rotate(model, model, 0.01, [0,0,1]);
            gl.uniformMatrix4fv(modelLoc, false, model);
            gl.uniformMatrix4fv(cameraLoc, false, this.cameraController.getMatrix);

            gl.drawArrays(gl.TRIANGLES, 0, 36);
        };

        draw();
    }
    public destroy() {
        // console.log('destroy!!');
        this.divHost.removeChild(this.canvas);
    }
}